-- One row per (UTC day, random daily id). The id is generated by the app,
-- changes every day and cannot be linked across days. No IP addresses,
-- user names, paths, commands or account data are stored.
CREATE TABLE IF NOT EXISTS pings (
  day        TEXT    NOT NULL,          -- YYYY-MM-DD (UTC)
  id         TEXT    NOT NULL,          -- 32 hex chars, random per install per day
  version    TEXT    NOT NULL,
  os         TEXT    NOT NULL,
  minutes    INTEGER NOT NULL DEFAULT 0, -- active minutes that day
  last_seen  INTEGER NOT NULL,          -- unix seconds, for the "live now" count
  PRIMARY KEY (day, id)
);
CREATE INDEX IF NOT EXISTS pings_last_seen ON pings (last_seen);
